sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // Get the JSON object sent in the request body
    //name=attachments base64


    var requestData = request.body.data;
    gs.info('From Scripted Rest API ' + requestData.name.toString());

    var gr = new GlideRecord("x_938076_backup_0_backup_scripts");
    gr.addEncodedQuery('name=' + requestData.name.toString());
    gr.query();
    if (gr.next()) {

        gs.info('From Scripted Rest API ' + ' Loop 1');
        // Access the properties from the requestData object, not the request object
        gr.name = requestData.name;
        gr.description = requestData.description;
        gr.script = requestData.script;
        gr.sys_scope = '66e8513383687210474659c6feaad331';

        var sysId = gr.update();
        var numberInc = gr.number;
        var responseBody = {
            "status": "success",
            "message": "Record Updated Successfully",
            "recordCreated": gr.sys_id
        };

    } else {
        gr.initialize();

        gs.info('From Scripted Rest API ' + ' Loop 2');
        gr.name = requestData.name;
        gr.description = requestData.description;
        gr.sys_scope = '66e8513383687210474659c6feaad331';
        gr.insert();

        var sysId = gr.update();
        var numberInc = gr.number;
        var responseBody = {
            "status": "success",
            "message": "Record Created Successfully",
            "recordUpdated": gr.sys_id
        };

    }

    response.setStatus(201);
    response.setBody(responseBody);




})(request, response);
